<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api, errorMessage } from '../services/api'
import { useFeedbackStore } from '../stores/feedback'
const feedback=useFeedbackStore(); const data=ref({products:[],categories:[],counts:{}}); const q=ref(''); const dialog=ref(false); const editing=ref(false); const imageFile=ref(null); const sortKey=ref('name'); const sortDesc=ref(false); const form=reactive({ref:'',name:'',product_type:'',category_slug:null,price:'0.00',pvp:null,colors:[],sizes:[],season:'ambos',quantity_step:12,sort_order:0,active:true,manual_active:true,description:''})
const categoryOptions=computed(()=>data.value.categories.map(category=>({title:category.active?category.label:`${category.label} (desativada)`,value:category.slug,disabled:!category.active})))
const products=computed(()=>{const value=q.value.toLowerCase();const rows=data.value.products.filter(p=>!value||`${p.ref} ${p.name} ${p.type} ${p.categoryLabel}`.toLowerCase().includes(value));const field={product:p=>`${p.name} ${p.ref}`,category:p=>p.categoryLabel||'',season:p=>p.season,price:p=>Number(p.price||0),pvp:p=>Number(p.pvp||0),active:p=>Number(Boolean(p.active&&p.categoryActive))}[sortKey.value]||((p)=>p.name);return rows.sort((a,b)=>{const left=field(a),right=field(b);const result=typeof left==='number'?left-right:String(left).localeCompare(String(right),'pt');return sortDesc.value?-result:result})})
function sortBy(key){if(sortKey.value===key)sortDesc.value=!sortDesc.value;else{sortKey.value=key;sortDesc.value=false}}
async function load(){try{data.value=(await api.get('/admin/catalog')).data}catch(e){feedback.show(errorMessage(e),'error')}}
function open(product=null){editing.value=Boolean(product);imageFile.value=null;Object.assign(form,product?{ref:product.ref,name:product.name,product_type:product.type,category_slug:product.categorySlug,price:product.price,pvp:product.pvp,colors:[...product.colors],sizes:[...product.sizes],season:product.season,quantity_step:product.quantityStep,sort_order:product.sortOrder,active:product.active,manual_active:product.manualActive,description:product.description}:{ref:'',name:'',product_type:'',category_slug:null,price:'0.00',pvp:null,colors:[],sizes:[],season:'ambos',quantity_step:12,sort_order:0,active:true,manual_active:true,description:''});dialog.value=true}
async function save(){try{const transaction=new FormData();transaction.append('payload',JSON.stringify(form));if(editing.value)transaction.append('original_ref',form.ref);const file=Array.isArray(imageFile.value)?imageFile.value[0]:imageFile.value;if(file)transaction.append('image',file);await api.post('/admin/products/save',transaction);dialog.value=false;await load();feedback.show(`Produto ${editing.value?'atualizado':'criado'}.`)}catch(e){feedback.show(errorMessage(e),'error')}}
async function toggle(product){const old=product.active;product.active=!old;try{await api.patch(`/admin/products/${product.ref}/active`,{active:product.active});feedback.show('Estado atualizado.')}catch(e){product.active=old;feedback.show(errorMessage(e),'error')}}
async function remove(product){if(!await feedback.confirm(`Eliminar definitivamente o produto “${product.name}”?`, 'Eliminar produto'))return;try{await api.delete(`/admin/products/${product.ref}`);await load();feedback.show('Produto eliminado.')}catch(e){feedback.show(errorMessage(e),'error')}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>Produtos</h1><p>{{ data.counts.totalProducts || 0 }} produtos · {{ data.counts.activeProducts || 0 }} ativos</p></div><v-btn color="primary" prepend-icon="mdi-plus" @click="open()">Novo produto</v-btn></div><v-card class="soft-card pa-4 mb-5"><v-text-field v-model="q" hide-details clearable prepend-inner-icon="mdi-magnify" label="Pesquisar produtos em tempo real" /></v-card>
  <v-card class="soft-card table-wrap"><v-table><thead><tr><th class="cursor-pointer" @click="sortBy('product')">Produto <v-icon size="14">{{sortKey==='product'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="cursor-pointer" @click="sortBy('category')">Categoria <v-icon size="14">{{sortKey==='category'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="cursor-pointer" @click="sortBy('season')">Estação <v-icon size="14">{{sortKey==='season'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="text-right cursor-pointer" @click="sortBy('price')">Preço s/ IVA <v-icon size="14">{{sortKey==='price'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="text-right cursor-pointer" @click="sortBy('pvp')">PVP <v-icon size="14">{{sortKey==='pvp'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th class="text-center cursor-pointer" @click="sortBy('active')">Ativo <v-icon size="14">{{sortKey==='active'?(sortDesc?'mdi-arrow-down':'mdi-arrow-up'):'mdi-swap-vertical'}}</v-icon></th><th></th></tr></thead><tbody><tr v-for="product in products" :key="product.ref" :class="{'opacity-60':!product.active||!product.categoryActive}"><td><div class="d-flex align-center ga-3"><v-avatar rounded="lg" color="grey-lighten-3"><v-img v-if="product.imageUrl" :src="product.imageUrl"/><v-icon v-else>mdi-package-variant</v-icon></v-avatar><div><b>{{ product.name }}</b><div class="text-caption">{{ product.ref }} · {{ product.type }}</div></div></div></td><td><span>{{ product.categoryLabel || 'Sem categoria' }}</span><v-chip v-if="!product.categoryActive" size="x-small" color="error" class="ml-2">Categoria off</v-chip></td><td><v-chip size="small" variant="tonal">{{ product.season }}</v-chip></td><td class="text-right font-weight-bold">{{ Number(product.price).toFixed(2) }} €</td><td class="text-right">{{ product.pvp == null ? '—' : `${Number(product.pvp).toFixed(2)} €` }}</td><td class="text-center"><v-switch :model-value="product.active" :disabled="!product.categoryActive && product.active" hide-details color="success" class="d-inline-flex" @update:model-value="toggle(product)" /></td><td class="text-no-wrap"><v-btn icon="mdi-pencil-outline" variant="text" @click="open(product)" /><v-btn icon="mdi-delete-outline" variant="text" color="error" @click="remove(product)" /></td></tr></tbody></v-table></v-card>
  <v-dialog v-model="dialog" max-width="850"><v-card><v-card-title class="pa-6 pb-2">{{ editing?'Editar produto':'Novo produto' }}</v-card-title><v-card-text class="pa-6"><v-row dense><v-col cols="12" md="4"><v-text-field v-model="form.ref" label="Referência" :disabled="editing" /></v-col><v-col cols="12" md="8"><v-text-field v-model="form.name" label="Nome" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.product_type" label="Tipo" /></v-col><v-col cols="12" md="6"><v-select v-model="form.category_slug" clearable label="Categoria" :items="categoryOptions" /></v-col><v-col cols="6" md="3"><v-text-field v-model="form.price" type="number" label="Preço s/ IVA" /></v-col><v-col cols="6" md="3"><v-text-field v-model="form.pvp" type="number" label="PVP" /></v-col><v-col cols="6" md="3"><v-select v-model="form.season" label="Estação" :items="[{title:'Todo o ano',value:'ambos'},{title:'Inverno',value:'inverno'},{title:'Verão',value:'verao'}]" /></v-col><v-col cols="6" md="3"><v-text-field v-model.number="form.quantity_step" type="number" min="1" label="Múltiplo" /></v-col><v-col cols="12" md="6"><v-combobox v-model="form.colors" multiple chips label="Cores" /></v-col><v-col cols="12" md="6"><v-combobox v-model="form.sizes" multiple chips label="Tamanhos" /></v-col><v-col cols="12"><v-file-input v-model="imageFile" accept="image/*,.heic,.heif,.tif,.tiff,.bmp,.gif" label="Imagem do produto" prepend-icon="mdi-camera-outline" hint="A imagem é validada e formatos incompatíveis são convertidos automaticamente." persistent-hint /></v-col><v-col cols="12"><v-textarea v-model="form.description" label="Descrição" rows="3" /></v-col><v-col cols="6"><v-switch v-model="form.active" color="success" label="Ativo" /></v-col><v-col cols="6"><v-switch v-model="form.manual_active" color="success" label="Ativação manual" /></v-col></v-row></v-card-text><v-card-actions class="px-6 pb-6"><v-spacer/><v-btn variant="text" @click="dialog=false">Cancelar</v-btn><v-btn color="primary" @click="save">Guardar</v-btn></v-card-actions></v-card></v-dialog>
</div></template>
